/** static void SwapPokeblockMenuItems(u32 id1, u32 id2) */
export function SwapPokeblockMenuItems(id1: any, id2: any): any {
  let i, count;
      let pokeblocks: any = gSaveBlock1Ptr.pokeblocks;
      let copyPokeblock1: any = null;

      if (id1 == id2)
          return;

      copyPokeblock1 = Alloc(0);
      copyPokeblock1 = pokeblocks[id1];

      if (id2 > id1)
      {
          id2--;
          for (count = id2, i = id1; i < count; i++)
              pokeblocks[i] = pokeblocks[i + 1];
      }
      else
      {
          for (count = id2, i = id1; i > count; i--)
              pokeblocks[i] = pokeblocks[i - 1];
      }

      pokeblocks[id2] = copyPokeblock1;
      Free(copyPokeblock1);
}

